export const lessons = [
  {
    id: 'hello', title: 'Hello, Milo', tag: 'Your first words', minutes: 3,
    intro: 'A program is a set of instructions. Start by telling Milo what to say.',
    concept: 'Put words inside quotes. Each say instruction starts a new line.',
    challenge: 'Add a second message to introduce yourself.',
    hint: 'On a new line, try: say "My name is Alex"',
    code: 'say "Hello, world!"\n',
    check: run => run.output.length >= 2,
    nextTip: 'Two instructions. Two messages. You just wrote a program.'
  },
  {
    id: 'variables', title: 'A name to remember', tag: 'Variables', minutes: 4,
    intro: 'A variable is a name for a value. Store something, then use its name.',
    concept: 'Use = to store a value. Use a comma to print words and a variable together.',
    challenge: 'Change Ada to your name, then run your greeting.',
    hint: 'Keep the quotes around your name. Leave name without quotes on the say line.',
    code: 'name = "Ada"\nsay "Hello", name\n',
    check: run => run.variables.some(v => v.name === 'name' && v.value !== 'Ada') && run.output.length > 0,
    nextTip: 'Change the value once and every use of name follows along.'
  },
  {
    id: 'square', title: 'Draw your first square', tag: 'Drawing + repetition', minutes: 5,
    intro: 'Meet your little drawing turtle. Give it a direction and let a loop do the work.',
    concept: 'move draws forward. turn rotates right. repeat runs the same instructions again.',
    challenge: 'Make the square blue, with sides of 120 steps.',
    hint: 'Change teal to blue and change move(100) to move(120). A square turns 90 degrees at each corner.',
    code: 'color("teal")\nwidth(3)\n\nrepeat 4\n    move(100)\n    turn(90)\nend\n',
    check: run => run.draw.filter(c => c.name === 'move' && c.args[0] === 120).length >= 4 && run.draw.some(c => c.name === 'color' && c.args[0] === 'blue'),
    nextTip: 'You changed two values and made the drawing your own.'
  },
  {
    id: 'pattern', title: 'Around we go', tag: 'Patterns', minutes: 5,
    intro: 'Small changes make new shapes. How many turns bring your turtle all the way around?',
    concept: 'A full turn is 360 degrees. Eight turns of 45 degrees make an octagon.',
    challenge: 'Draw an octagon with eight sides and a 45 degree turn.',
    hint: 'Change repeat 6 to repeat 8, and turn(60) to turn(45).',
    code: 'color("purple")\nwidth(3)\n\nrepeat 6\n    move(60)\n    turn(60)\nend\n',
    check: run => run.draw.filter(c => c.name === 'move').length === 8 && run.draw.filter(c => c.name === 'turn' && c.args[0] === 45).length === 8,
    nextTip: 'You found a connection between code and geometry.'
  },
  {
    id: 'ask', title: 'Let your program listen', tag: 'Questions', minutes: 5,
    intro: 'Programs can listen, too. ask waits for your answer and stores the words you type.',
    concept: 'Answer the question in the Messages panel. Your answer becomes the value of favorite.',
    challenge: 'Answer with blue, pink, purple, or another color to personalize the square.',
    hint: 'Click Run, type a color in Messages, then choose Send answer. Try a second color on another run.',
    code: 'favorite = ask("What color should I draw? ")\nsay "You chose", favorite\ncolor(favorite)\n\nrepeat 4\n    move(90)\n    turn(90)\nend\n',
    check: run => run.answers.length > 0 && run.draw.some(c => c.name === 'color') && run.output.length > 0,
    nextTip: 'Your program responded to a real person: you.'
  },
  {
    id: 'choices', title: 'Choose a path', tag: 'Decisions', minutes: 6,
    intro: 'An if instruction lets a program choose what to do.',
    concept: 'ask returns words. number turns a numeric answer into a number you can compare.',
    challenge: 'Run the program with a number below 10, then try a number of 10 or more.',
    hint: 'Only one branch runs each time. Change the messages if you want to make them your own.',
    code: 'age = number(ask("How old is your explorer? "))\n\nif age >= 10\n    say "Take the mountain trail."\nelse\n    say "Take the forest trail."\nend\n',
    check: run => run.answers.length > 0 && run.output.some(line => /trail/.test(line)),
    nextTip: 'The same program can follow different paths. Try the other answer next.'
  },
  {
    id: 'counter', title: 'Count as you create', tag: 'Loop counters', minutes: 6,
    intro: 'A loop can tell you which turn it is on. Use that number to grow a pattern.',
    concept: 'repeat 6 as count gives count the values 1 through 6. Multiplication uses *.',
    challenge: 'Print count inside the loop, so Messages shows 1 through 6.',
    hint: 'Add say count after the repeat line. Keep it before end.',
    code: 'color("orange")\nwidth(3)\n\nrepeat 6 as count\n    move(count * 12)\n    turn(60)\nend\n',
    check: run => ['1','2','3','4','5','6'].every(value => run.output.includes(value)),
    nextTip: 'One changing number can control a whole pattern.'
  },
  {
    id: 'functions', title: 'Make a new tool', tag: 'Functions', minutes: 7,
    intro: 'A function gives a name to a group of instructions. Make a petal tool and use it again.',
    concept: 'function defines your tool. petal() uses it. circle draws around the turtle without moving it.',
    challenge: 'Change the loop to draw six petals.',
    hint: 'Keep the function as it is. Change repeat 3 to repeat 6.',
    code: 'function petal()\n    circle(35)\n    move(35)\n    turn(60)\nend\n\ncolor("pink")\nwidth(3)\nrepeat 3\n    petal()\nend\n',
    check: run => run.draw.filter(c => c.name === 'circle').length === 6,
    nextTip: 'You made a reusable instruction of your own.'
  },
  {
    id: 'quiz', title: 'Build a tiny quiz', tag: 'Your first game', minutes: 7,
    intro: 'Combine a question, a number, and a decision to make a little quiz.',
    concept: 'Use == to compare two values. Use = to store a value. They do different jobs.',
    challenge: 'Answer correctly once, then change the question and its correct answer.',
    hint: 'The starter question has the answer 5. If you change the question to 4 + 4, also change == 5 to == 8.',
    code: 'answer = number(ask("What is 2 + 3? "))\n\nif answer == 5\n    say "You got it!"\nelse\n    say "Try the question again."\nend\n',
    check: run => run.answers.length > 0 && run.output.includes('You got it!'),
    nextTip: 'You built the question and the rule that checks an answer.'
  },
  {
    id: 'studio', title: 'Your own little studio', tag: 'Make it yours', minutes: 8,
    intro: 'Bring your tools together. Make a picture that belongs to you.',
    concept: 'A function parameter lets the same tool draw at different sizes. pen_up moves without drawing.',
    challenge: 'Draw two stars in different colors. Use your star function for both.',
    hint: 'After the first star, try pen_up(), turn(90), move(150), pen_down(), color("purple"), and star(60).',
    code: 'function star(size)\n    repeat 5\n        move(size)\n        turn(144)\n    end\nend\n\ncolor("gold")\nwidth(3)\nstar(120)\n',
    check: run => run.draw.filter(c => c.name === 'move').length >= 10 && new Set(run.draw.filter(c => c.name === 'color').map(c => c.args[0])).size >= 2,
    nextTip: 'Keep experimenting. You now have the tools to invent your own drawings and games.'
  },
  {
    id: "animation",
    title: "Make it move",
    tag: "Animation + timing",
    minutes: 6,
    intro: "A moving picture is a series of still pictures. Draw, wait, then draw the next frame.",
    concept: "wait pauses for seconds. clear erases the previous frame. Drawing pace adds a little time between instructions; Quick is best for animation.",
    challenge: "Make the dot move through six frames. Use Quick drawing pace to see your timing clearly.",
    hint: "Change repeat 3 to repeat 6. Keep wait(0.25) inside the loop. Try a longer wait after you finish.",
    code: "color(\"gold\")\n\nrepeat 3 as frame\n    clear()\n    go_to(frame * 40 - 140, 0)\n    dot(40)\n    wait(0.25)\nend\n",
    nextTip: "Each frame is a new picture. Save your animation as a project and try changing its speed.",
    check: run => run.waits.length >= 6 && run.draw.filter(c => c.name === 'dot').length === 6 && new Set(run.draw.filter(c => c.name === 'go_to').map(c => c.args[0])).size === 6
  },
  {
    id: "keyboard",
    title: "Control your turtle",
    tag: "Keyboard input",
    minutes: 7,
    intro: "Your program can wait for a direction from you. Use your keyboard or the on-screen buttons.",
    concept: "key() waits for one new arrow or Space press. It returns the words up, down, left, right, or space. A key you hold down counts once.",
    challenge: "Run your program and use both Left and Right during its four turns. Try Space on another run to change the color.",
    hint: "After Run, use the green direction panel. Press Left and Right at least once each, then choose two more directions to finish.",
    code: "x = 0\ny = 0\ncolor(\"teal\")\n\nrepeat 4\n    direction = key()\n    if direction == \"up\"\n        y = y + 40\n    else if direction == \"down\"\n        y = y - 40\n    else if direction == \"left\"\n        x = x - 40\n    else if direction == \"right\"\n        x = x + 40\n    else\n        color(\"purple\")\n    end\n    go_to(x, y)\n    dot(20)\nend\nsay \"You are the controller!\"\n",
    nextTip: "You made a program respond to your choices. Try eight turns, or add a wait between moves.",
    check: run => run.keys.includes('left') && run.keys.includes('right') && run.draw.filter(c => c.name === 'dot').length === 4
  },
  {
    id: "sprites",
    title: "Collect your first star",
    tag: "Sprites + touching",
    minutes: 8,
    intro: "Make a little game with two independent objects: a turtle you control and a star to collect.",
    concept: "sprite creates an object. place sets its position. shift moves it without erasing the picture. touching checks their round touch areas. hide makes the star disappear.",
    challenge: "Guide your turtle to the star. Collect it before the twenty turns finish.",
    hint: "Click Run and press Right four times. Space uses a turn without moving. Change the starting positions once you have collected your first star.",
    code: "player = sprite(\"turtle\", \"teal\")\nstar = sprite(\"star\", \"gold\")\nplace(player, -100, 0)\nplace(star, 100, 0)\nfound = false\n\nrepeat 20\n    direction = key()\n    if direction == \"right\"\n        shift(player, 40, 0)\n    else if direction == \"left\"\n        shift(player, -40, 0)\n    else if direction == \"up\"\n        shift(player, 0, 40)\n    else if direction == \"down\"\n        shift(player, 0, -40)\n    end\n\n    if touching(player, star)\n        hide(star)\n        found = true\n        say \"You found the star!\"\n        break\n    end\nend\n\nif not found\n    say \"Try again. Guide your turtle to the star.\"\nend\n",
    nextTip: "You built a game with a player, a goal, and a win condition. Save it in My projects and make it your own.",
    check: run => run.keys.length > 0 && run.output.includes('You found the star!') && run.draw.some(c => c.name === 'sprite_state' && c.args[1] === 'star' && c.args[5] === false)
  },
  {
    id: "five-stars",
    title: "Collect five stars",
    tag: "Sound + chance + score",
    minutes: 10,
    intro: "Turn your first game into a new adventure every time. Each collected star adds a point and plays a note.",
    concept: "random(min, max) chooses a whole number, including both ends. show_score displays a number above the canvas. play_note uses a note number and a duration in seconds.",
    challenge: "Collect five stars in one run. Use the arrows to guide your turtle to each new position.",
    hint: "Follow the gold star. You have 120 turns. Use Quick drawing pace for snappier controls. Toggle Sound off if you prefer a quiet game; it still works.",
    code: "score = 0\nshow_score(score)\nplayer = sprite(\"turtle\", \"teal\")\nstar = sprite(\"star\", \"gold\")\nplace(star, random(-4, 4) * 40, random(-4, 4) * 40)\nsay \"Collect five stars. Use the arrow keys!\"\n\nrepeat 120\n    direction = key()\n    if direction == \"right\"\n        shift(player, 40, 0)\n    else if direction == \"left\"\n        shift(player, -40, 0)\n    else if direction == \"up\"\n        shift(player, 0, 40)\n    else if direction == \"down\"\n        shift(player, 0, -40)\n    end\n\n    if touching(player, star)\n        score = score + 1\n        show_score(score)\n        play_note(72, 0.15)\n        if score == 5\n            hide(star)\n            say \"You collected five stars!\"\n            break\n        end\n        place(star, random(-4, 4) * 40, random(-4, 4) * 40)\n    end\nend\n\nif score < 5\n    say \"You collected\", score, \"stars. Try again!\"\nend\n",
    nextTip: "You combined chance, sound, a score, and a win condition. Try a different note number or change the goal to ten stars.",
    check: run => run.scores.includes(0) && run.scores.includes(5) && run.notes.length >= 5 && run.output.includes('You collected five stars!')
  }
];

