  {name:"Collect five stars", code:"score = 0\nshow_score(score)\nplayer = sprite(\"turtle\", \"teal\")\nstar = sprite(\"star\", \"gold\")\nplace(star, random(-4, 4) * 40, random(-4, 4) * 40)\nsay \"Collect five stars. Use the arrow keys!\"\n\nrepeat 120\n    direction = key()\n    if direction == \"right\"\n        shift(player, 40, 0)\n    else if direction == \"left\"\n        shift(player, -40, 0)\n    else if direction == \"up\"\n        shift(player, 0, 40)\n    else if direction == \"down\"\n        shift(player, 0, -40)\n    end\n\n    if touching(player, star)\n        score = score + 1\n        show_score(score)\n        play_note(72, 0.15)\n        if score == 5\n            hide(star)\n            say \"You collected five stars!\"\n            break\n        end\n        place(star, random(-4, 4) * 40, random(-4, 4) * 40)\n    end\nend\n\nif score < 5\n    say \"You collected\", score, \"stars. Try again!\"\nend\n"},
  {name:"A little melody", code:"say \"A little melody\"\nfor note in [60, 64, 67, 72]\n    play_note(note, 0.25)\nend\n"},
  {name:"Collect the star", code:"background(\"#eef4e7\")\ncolor(\"teal\")\ngo_to(-195, 190)\nwrite(\"Collect the star!\")\nplayer = sprite(\"turtle\", \"teal\")\nstar = sprite(\"star\", \"gold\")\nplace(player, -100, 0)\nplace(star, 100, 80)\nfound = false\n\nrepeat 40\n    direction = key()\n    if direction == \"right\"\n        shift(player, 40, 0)\n    else if direction == \"left\"\n        shift(player, -40, 0)\n    else if direction == \"up\"\n        shift(player, 0, 40)\n    else if direction == \"down\"\n        shift(player, 0, -40)\n    end\n\n    if touching(player, star)\n        hide(star)\n        found = true\n        say \"You found the star!\"\n        break\n    end\nend\n\nif not found\n    say \"Try again. Guide your turtle to the star.\"\nend\n"},
  {name:'A little shape village', code:'background("#f4f8ea")\nwidth(3)\n\n# A house made from two shapes\ngo_to(-70, -30)\ncolor("brown")\nfill("gold")\nrectangle(130, 110)\n\ngo_to(-70, 65)\nfill("coral")\npolygon(3, 85)\n\n# A door and two windows\ngo_to(-70, -55)\nfill("brown")\nrectangle(26, 60)\nfill("skyblue")\ngo_to(-108, -10)\nrectangle(24, 28)\ngo_to(-32, -10)\nrectangle(24, 28)\n\n# A sun and a tree\ncolor("gold")\ngo_to(135, 145)\ndot(65)\ncolor("brown")\nfill("brown")\ngo_to(110, -90)\nrectangle(20, 70)\ncolor("green")\nfill("green")\ngo_to(110, -25)\npolygon(3, 75)\n'},
  {name:'A page of colorful shapes', code:'background("#faf8f0")\nwidth(3)\n\ngo_to(-130, 90)\ncolor("purple")\nfill("lavender")\ncircle(55)\n\ngo_to(90, 90)\ncolor("teal")\nfill("turquoise")\nrectangle(100, 75)\n\ngo_to(-130, -95)\ncolor("orange")\nfill("gold")\npolygon(5, 60)\n\ngo_to(90, -95)\ncolor("pink")\ndot(100)\n\nno_fill()\ncolor("purple")\ncircle(65)\n'},
  {name:'Rainbow spiral', code:'width(3)\ncolors = ["teal", "purple", "pink", "orange", "blue"]\n\nrepeat 60 as step\n    color(colors[(step - 1) % 5])\n    move(step * 3)\n    turn(91)\nend\n'},
  {name:'A field of stars', code:'function star(size)\n    repeat 5\n        move(size)\n        turn(144)\n    end\nend\n\ncolor("gold")\nwidth(3)\nstar(120)\npen_up()\nturn(90)\nmove(140)\npen_down()\ncolor("purple")\nstar(60)\n'},
  {name:'Friendly greeter', code:'name = ask("What is your name? ")\nsay "Hello", name\nsay "What will you make today?"\n'},
  {name:'A number guessing game', code:'guess = number(ask("Guess a number from 1 to 5. "))\n\nif guess == 3\n    say "You found my number!"\nelse if guess < 3\n    say "My number is higher. Try again."\nelse\n    say "My number is lower. Try again."\nend\n'}
