export const commands = [
  ['random(-4, 4)','Choose a random whole number, including both ends. Bounds must be whole numbers from -1000000 to 1000000; put the smaller one first. Each run can give new results.'],
  ['play_note(72, 0.2)','Play a soft note and wait for its duration. Notes 48 to 84 are supported (60 is middle C). Duration: 0.05 to 2 seconds. Sound off keeps the same timing. Pause/Stop silence the current note; Continue does not replay it.'],
  ['show_score(score)','Display a whole-number score from 0 to 1000000 above the canvas. Call again whenever it changes. A new run resets the score panel.'],
  ['player = sprite("turtle", "teal")','Create a turtle, star, circle, or square. Color is optional. Each sprite has a round touch area 40 steps across. Up to 64 sprites per run.'],
  ['place(player, -100, 0)','Set a sprite position. The center is (0, 0); positive x is right, positive y is up. Positions stop at -230 and 230 to keep sprites on the canvas.'],
  ['shift(player, 20, 0)','Move a sprite by x and y amounts. This keeps drawings and other sprites in place. Sprite commands do not move the drawing turtle.'],
  ['touching(player, star)','Returns true when two visible sprites’ round touch areas meet (centers at most 40 steps apart). Hidden sprites never touch.'],
  ['hide(star) / show(star)','Hide a sprite or bring it back in the same position. It still exists while hidden.'],
  ['color(player, "purple")','Change one sprite’s color. color("purple") still changes the drawing pen.'],
  ['wait(0.25)','Pause for seconds, from 0 to 60. Use Quick drawing pace for animations. Pause freezes the remaining wait; Stop ends it immediately.'],
  ['direction = key()','Wait for one new arrow or Space press. Returns "up", "down", "left", "right", or "space". Use the green direction panel with a keyboard, mouse, or touch. Holding a key counts once.'],
  ['say "Hello"','Show a message. Separate values with commas.'],
  ['name = "Ada"','Store a value in a variable.'],
  ['ask("Your name? ")','Ask a question in Messages. The answer is text.'],
  ['number("12")','Turn numeric text into a number.'],
  ['repeat 4\n    move(100)\nend','Repeat the instructions inside a block.'],
  ['repeat 4 as count','Repeat with a counter starting at 1. Close the block with end.'],
  ['if score >= 5\n    say "Great"\nelse\n    say "Try again"\nend','Choose between two sets of instructions.'],
  ['function double(n)\n    return n * 2\nend','Define your own tool, then call double(5).'],
  ['go_to(-100, 50)','Jump without drawing. The center is (0, 0). Positive x goes right; positive y goes up. The visible canvas runs from -250 to 250.'],
  ['dot(60)','Draw a filled dot in the pen color. 60 is its width across, called its diameter.'],
  ['fill("gold")','Choose the inside color for circle, rectangle, and polygon shapes. This does not fill paths drawn with move.'],
  ['no_fill()','Return to drawing shape outlines. Dots always stay filled.'],
  ['rectangle(100, 60)','Draw a centered rectangle, 100 steps wide and 60 high. The turtle stays in place.'],
  ['polygon(5, 60)','Draw a centered regular polygon. Choose 3 to 36 sides; 60 is the distance from its center to a corner. The first corner points where the turtle faces.'],
  ['move(100)','Move the turtle forward 100 steps.'],
  ['turn(90)','Turn right 90 degrees. Negative numbers turn left.'],
  ['color("teal")','Choose a pen color: blue, teal, pink, purple, orange, gold, and more. Hex colors also work.'],
  ['width(3)','Choose how thick your pen draws.'],
  ['pen_up() / pen_down()','Travel without drawing, then start drawing again.'],
  ['circle(40)','Draw a circle centered on the turtle. The turtle stays in place.'],
  ['home()','Return to the middle, facing up, without drawing.'],
  ['clear()','Erase the drawing and return the drawing turtle to the middle. Sprites stay in place. A new run resets everything.'],
  ['background("white")','Change the canvas background.'],
  ['write("Hello")','Write words at the turtle position.'],
  ['items = ["red", "blue"]','Make a list. items[0] is its first item.'],
  ['for item in items\n    say item\nend','Visit each item in a list.']
];
